def get_trade_strategy(user_id, trade_id):
    usercode_dat_file = os.path.join(TRADE_DIR_PATH, user_id, 'result', trade_id, USER_CODE_DAT)
    strategy_profile_file_path = os.path.join(STRATEGY_DIR_PATH, user_id, STRATEGY_PROFILE)
    if os.path.exists(usercode_dat_file):
        strategy = json.JSONDecoder().decode(json.load(open(usercode_dat_file, 'r')))
        strategy_id = strategy.get('id')
        if strategy['business_mode'] == BUSINESS_MODE_1:
            strategy['content'] = ''
        elif 'is_encryption' in strategy.keys() and strategy['is_encryption'] in (ENCRYPTION_MODE_1, ENCRYPTION_MODE_2):
            error_no, error_info, session_key, session_iv = PyRead_AES_Binary(strategy_profile_file_path, strategy_id)
            if error_no == 0:
                strategy['content'] = aes_decrypt(strategy['content'], session_key.decode('utf-8'), session_iv.decode('utf-8'))
            else:
                app_log.info('error_encryption:%s' % error_info)
        return strategy
