def check_trade(user_id, trade_name, trade_unit, trade_id):
    trade_name = html.escape(trade_name)
    checkname = check_trade_name(user_id, trade_name)
    tempTradeUnits = []
    if checkname:
        return checkname
    else:
        update_result = add_user_info(user_id, trade_id, trade_unit)
        if update_result:
            trade_user_path = f'{TRADE_DIR_PATH!s}/{user_id!s}'
            if not os.path.exists(trade_user_path):
                os.mkdir(trade_user_path)
