def trade_count(trade_list_file):
    """
    统计用户正在进行中的模拟交易个数
    """
    count = 0
    try:
        if os.path.exists(trade_list_file):
            with FileLock(trade_list_file, mode='shared'):
                csv_reader = FileIO(trade_list_file).read(return_type='csv_reader')
            for line in csv_reader:
                if line[2] == '0' or line[2] == '3':
                    count += 1
                if count >= max_trade_count:
                    break
                continue
        else:
            app_log.error('%s文件不存在，无法统计运行中交易个数' % trade_list_file)
        return count
        return None
    except BaseException:
        app_log.error(f'读取{trade_list_file!s}文件失败，错误为{get_traceback_message()!s}')
        return count
