def verify_user_py_code(path):
    with subprocess.Popen(['pyflakes', path], stdout=subprocess.PIPE, stderr=subprocess.PIPE) as proc:
        out, err = proc.communicate()
        error = get_pyflakes_error_info(err.decode('utf-8'))
        if error:
            CompileError(error)
def get_pyflakes_error_info(error_info, path=None):
    if not error_info:
        return None
    elif path is None:
        reg = re.compile(pyflakes_error_template)
        regMatch = reg.match(error_info)
        if regMatch is not None:
            path = regMatch.groupdict()['path']
    line_no_start = len(path) + 1
    line_no_end = error_info.find(':', line_no_start)
    line_no = int(error_info[line_no_start:line_no_end]) - 3
    info_return = ''.join(['用户策略', str(line_no), error_info[line_no_end:]])
    return info_return
