def trade_status_check_hg(user_id, sys_strategy_type='hg'):
    error_no = 0
    trade_params = {}
    sim_tradding_list_file = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
    if os.path.exists(sim_tradding_list_file):
        try:
            with FileLock(sim_tradding_list_file, mode='shared'):
                df = FileIO(sim_tradding_list_file).read(return_type='dataframe', index_col=0, dtype=str)
            if sys_strategy_type == 'hg':
                df = df[df['strategyType'] == AI_ADD_TRADE_STRATEGY_TYPE]
            elif sys_strategy_type == 'zt':
                df = df[df['strategyType'] == ZT_ADD_TRADE_STRATEGY_TYPE]
            else:
                app_log.error('入参的策略类型有误，入参为：%s' % sys_strategy_type)
                error_no = -1
                return (error_no, trade_params)
            if len(df) > 0:
                df = df[df['status'] == '0']
                if len(df) > 0:
                    df = df[-1:]
                    for i in df.index:
                        trade_params['trade_id'] = i
                        trade_params['trade_name'] = df['name'][i]
                        trade_params['trade_status'] = df['status'][i]
                        trade_params['frequency'] = df['frequency'][i]
                        trade_params['start_date'] = df['startTime'][i]
                        trade_params['strategy_id'] = df['backtestContentId'][i]
                    else:
                        return (error_no, trade_params)
            trade_params = {'trade_status': 1}
            return (error_no, trade_params)
        except BaseException:
            app_log.error('检查用户交易状态失败，错误原因：%s' % get_traceback_message())
            error_no = -1
            return (error_no, trade_params)
    else:
        app_log.error('用户%s交易信息文件不存在' % user_id)
        trade_params = {'trade_status': 1}
        return (error_no, trade_params)
def get_code_setup(file_path, strategy_path=None):
    """
    获取setup.py代码
    :param file_path:
    :return:
    """
    if strategy_path is None:
        strategy_path = os.path.join(file_path, 'user_strategy.py')
    code_str = f'\ntry:\n    from setuptools import setup, Extension, find_packages\nexcept ImportError:\n    from distutils.core import setup\n    from distutils.extension import Extension\nfrom Cython.Build import cythonize\nimport numpy\n\nsetup(\n  name = \'user_strategy\',\n  ext_modules = cythonize(Extension(\n      \'user_strategy\',\n      language=\'c++\',\n      sources=[\'{strategy_path!s}\'],\n      include_dirs=[numpy.get_include()],\n      extra_compile_args=["-std=c++11"],\n      extra_link_args=["-lstdc++"],\n  ), language_level=3),\n  ext_package = \'{file_path!s}\'\n)\n'
    return code_str
def get_dir_file_name(file_path, postfix):
    """
    获取指定目录指定后缀文件名
    :param file_path:
    :param postfix: 后缀名，如.txt
    :return: 文件名列表，不包含路径
    """
    file_name_list = []
    f_list = os.listdir(file_path)
    for _file in f_list:
        if os.path.splitext(_file)[1] == postfix:
            file_name_list.append(_file)
    else:
        return file_name_list
def check_and_update_trade(run_log, user_id_list, restart_mode=None):
    """
    检查交易进程并更新交易状态
    :param run_log: 记录日志方法
    :type run_log: logging.Logger
    :param user_id_list: 用户列表
    :type user_id_list: list
    :param restart_mode: 拉起交易模式：缺省，只检查IP等于本机IP的交易；1，检查全部交易。
    :type restart_mode: str
    """
    for user_id in user_id_list:
        count = 0
        while count < 3:
            try:
                trade_list_file = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
                with FileLock(trade_list_file):
                    file_io = FileIO(trade_list_file)
                    csv_reader = file_io.read(return_type='csv_reader')
                    write_info = []
                    file_io = FileIO(trade_list_file)
                    csv_reader = file_io.read(return_type='csv_reader')
                    write_info = []
                    for items in csv_reader:
                        if items[2] in ('0', '5'):
                            trade_id = items[0]
                            trade_ip = items[15]
                            if restart_mode is None and trade_ip != LOCAL_IP:
                                run_log.warning('账户{}交易ID{}启动交易IP{}与当前服务器IP{}不相等，跳过交易进程检查'.format(user_id, trade_id, trade_ip, LOCAL_IP))
                            else:
                                output = os.popen(GREP_CMD % trade_id)
                                trade_id_match = re.findall(trade_id, output.read())
                                if len(trade_id_match) == 0:
                                    items[2] = '5'
                                    run_log.warning('账户{}交易ID{}进程数为0，交易状态更新为5(待重启)，请检查后重新执行'.format(user_id, trade_id))
                                else:
                                    items[2] = '0'
                                    run_log.info('账户{}交易ID{}进程数为{}，交易状态更新为0(运行中)'.format(user_id, trade_id, len(trade_id_match)))
                        write_info.append(items)
                    if len(write_info) > 0:
                        file_io.write(write_info, mode='w', data_type='list')
                        os.system('chmod -R 777 {}'.format(trade_list_file))
                        os.system('chown -R fly:fly {}'.format(trade_list_file))
            except BaseException:
                if count == 2:
                    run_log.error('账户{}更新交易信息失败，错误原因：{}'.format(user_id, get_traceback_message()))
                count += 1
                time.sleep(1)
            else:
                break
def set_trade_status(trade_id, status, user_id=None):
    """
    设置交易状态
    :param trade_id: 交易ID
    :type trade_id: str
    :param status: 交易状态
    :type status: str
    :param user_id: 用户ID(宿主机调用时传入)
    :type user_id: str
    :return: 是否设置成功
    :rtype: bool
    """
    count = 1
    exchange_flag = False
    if user_id is not None:
        sim_trading_list_path = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
    else:
        sim_trading_list_path = os.path.join(TRADE_DIR_PATH, SIM_TRADING_LIST_FILE)
    if os.path.exists(sim_trading_list_path):
        while count <= 3:
            try:
                with FileLock(sim_trading_list_path):
                    file_io = FileIO(sim_trading_list_path)
                    csv_reader = file_io.read(return_type='csv_reader')
                    write_info = []
                    for items in csv_reader:
                        if len(items) > 0:
                            if items[0] == trade_id:
                                items[2] = status
                                exchange_flag = True
                            write_info.append(items)
                    if len(write_info) > 0 and exchange_flag is True:
                        file_io.write(write_info, mode='w', data_type='list')
                break
            except BaseException:
                system_log.error(f'第{count!s}次设置交易状态失败，错误原因：{get_traceback_message()!s}')
                count += 1
                time.sleep(0.5)
        else:
            return exchange_flag
    else:
        system_log.error('%s文件不存在，无法修改交易状态' % sim_trading_list_path)
    return exchange_flag
def set_trade_stop_status(trade_id, user_id=None):
    """
    设置交易停止状态
    :param trade_id: 交易ID
    :type trade_id: str
    :param user_id: 用户ID(宿主机调用时传入)
    :type user_id: str
    :return: 是否设置成功
    :rtype: bool
    """
    return set_trade_status(trade_id, TradeStatus.TRADE_STOP, user_id=user_id)
def set_trade_running_status(trade_id, user_id=None):
    """
    设置交易运行状态
    :param trade_id: 交易ID
    :type trade_id: str
    :param user_id: 用户ID(宿主机调用时传入)
    :type user_id: str
    :return: 是否设置成功
    :rtype: bool
    """
    return set_trade_status(trade_id, TradeStatus.TRADE_RUNNING, user_id=user_id)
def get_trade_status(trade_id, user_id=None, return_trade_info=False):
    """
    获取交易状态
    
    :param trade_id: 交易ID
    :type trade_id: str
    :param user_id: 用户ID(宿主机调用时传入)
    :type user_id: str
    :param return_trade_info: 是否返回交易ID对应的交易信息
    :type return_trade_info: bool
    :return: 如果 `return_trade_info` 为 False，则返回 交易状态；否则，返回交易信息
    :rtype: str 或 list
    """
    trade_status = TradeStatus.TRADE_STOP
    if user_id is not None:
        sim_trading_list_path = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
    else:
        sim_trading_list_path = os.path.join(TRADE_DIR_PATH, SIM_TRADING_LIST_FILE)
    count = 1
    if os.path.exists(sim_trading_list_path):
        while count <= GET_TRADE_STATUS_TIME:
            try:
                with FileLock(sim_trading_list_path, mode='shared'):
                    file_io = FileIO(sim_trading_list_path)
                    csv_reader = file_io.read(return_type='csv_reader')
                for items in csv_reader:
                    if len(items) > 0:
                        if items[0] == trade_id:
                            if return_trade_info:
                                return items
                            else:
                                return items[2]
                        continue
                    system_log.warning('sim_backtest_list.csv文件为空')
                    continue
            except BaseException:
                system_log.error('第{}次获取交易状态失败，错误原因：{}'.format(count, get_traceback_message()))
                count += 1
                time.sleep(1)
            else:
                break
        else:
            if return_trade_info:
                return ['', '', trade_status]
            else:
                return trade_status
    else:
        system_log.error('{}文件不存在，无法获取交易状态'.format(sim_trading_list_path))
    if return_trade_info:
        pass
def query_trade_strategy_info(user_id, strategy_id):
    trade_status = [TradeStatus.TRADE_RUNNING, TradeStatus.TRADE_PRE_RESTART]
    sim_trading_list_path = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
    if os.path.exists(sim_trading_list_path):
        try:
            with FileLock(sim_trading_list_path, mode='shared'):
                file_io = FileIO(sim_trading_list_path)
                csv_reader = file_io.read(return_type='csv_reader')
            for items in csv_reader:
                if len(items) > 0 and items[2] in trade_status and items[7] == strategy_id and items[16] == 'app':
                    break
            return True
        except BaseException:
            system_log.error('获取交易状态失败，错误原因：{}'.format(get_traceback_message()))
def query_strategy_id(user_id, trade_id):
    trade_status = [TradeStatus.TRADE_RUNNING, TradeStatus.TRADE_PRE_RESTART]
    sim_trading_list_path = os.path.join(TRADE_DIR_PATH, user_id, SIM_TRADING_LIST_FILE)
    if os.path.exists(sim_trading_list_path):
        try:
            with FileLock(sim_trading_list_path, mode='shared'):
                file_io = FileIO(sim_trading_list_path)
                df = file_io.read(return_type='dataframe')
            trade_df = df[df['id'] == trade_id]
            if len(trade_df) == 1:
                return trade_df.backtestContentId.iloc[0]
        except BaseException:
            system_log.error('获取交易streagy_id异常，错误原因：{}'.format(get_traceback_message()))
            time.sleep(1)
